    return {
        'numFmt': cell.number_format,
        'font': (f.name, f.sz, f.b, f.i, f.u, f.strike, f.vertAlign, f.outline, f.shadow, f.condense, f.extend, color(f.color), f.family, f.charset, f.scheme),
