        'border': (b.left.style, color(b.left.color), b.right.style, color(b.right.color), b.top.style, color(b.top.color), b.bottom.style, color(b.bottom.color), b.diagonal.style, color(b.diagonal.color), b.diagonalUp, b.diagonalDown, b.outline),
        'align': (a.horizontal, a.vertical, a.text_rotation, a.wrap_text, a.shrink_to_fit, a.indent, a.relativeIndent, a.justifyLastLine, a.readingOrder),
        'prot': (p.locked, p.hidden),
        'quotePrefix': cell.quotePrefix,
    }
diffs=[]
